starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "cluster_name" {
  description = "Input variable cluster_name."
  type        = string
  default     = "app-cluster"
}

variable "family" {
  description = "Input variable family."
  type        = string
  default     = "app-task"
}

variable "container_image" {
  description = "Input variable container_image."
  type        = string
  default     = "nginx:alpine"
}

variable "vpc_id" {
  description = "Input variable vpc_id."
  type        = string
}

variable "subnet_ids" {
  description = "Input variable subnet_ids."
  type        = list(string)
}

variable "security_group_ids" {
  description = "Input variable security_group_ids."
  type        = list(string)
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_ecs_cluster" "this" {
  name = "app-cluster"
}

resource "aws_ecs_task_definition" "this" {
  family                   = "app-task"
  cpu                      = 256
  memory                   = 512
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  container_definitions    = jsonencode([{ name = "app", image = "nginx:alpine", essential = true }])
}

resource "aws_ecs_service" "this" {
  # TODO - Complete the aws_ecs_service resource.
  # Add the arguments and nested blocks required for aws_ecs_service.
}

resource "aws_lb" "this" {
  name               = "app-alb"
  load_balancer_type = "application"
}

resource "aws_lb_target_group" "this" {
  name     = "app-tg"
  port     = 80
  protocol = "HTTP"
  health_check {
    path = "/"
  }
}

resource "aws_lb_listener" "this" {
  port     = 80
  protocol = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }
}

starter.outputs.tf:
output "cluster_arn" {
  value = aws_ecs_cluster.this.arn
}

output "service_name" {
  value = aws_ecs_service.this.id
}
